#!/usr/bin/env bash
cd "$(dirname "$0")" && read -rp "App name [myapp]: " APP && read -rp "Domain [example.com]: " DOM && APP=${APP:-myapp} DOM=${DOM:-example.com} && [[ $APP =~ ^[a-z0-9_-]+$ ]] && S() { sed -e "s#/var/www/myapp#/var/www/$APP#g" -e "s#example\.com#$DOM#g" "$1"; } && { id deploy &>/dev/null || adduser --disabled-password --gecos "" deploy; } && mkdir -p /var/www/$APP/{bin,releases,shared/static} && chown -R deploy:deploy /var/www/$APP && S deploy.sh | install -m 755 -o deploy -g deploy /dev/stdin /var/www/$APP/bin/deploy.sh && S nextjs_.service | install -m 644 /dev/stdin /etc/systemd/system/nextjs@.service && install -m 644 -o deploy -g deploy nextjs-upstream.conf /etc/nginx/nextjs-upstream.conf && S nginx-myapp.conf | install -m 644 /dev/stdin /etc/nginx/conf.d/$APP.conf && visudo -cf sudoers-deploy && install -m 440 sudoers-deploy /etc/sudoers.d/deploy && { [ -f /var/www/$APP/shared/.env.production ] || echo "NEXT_SERVER_ACTIONS_ENCRYPTION_KEY=$(openssl rand -base64 32)" | install -m 600 -o deploy -g deploy /dev/stdin /var/www/$APP/shared/.env.production; } && systemctl daemon-reload && systemctl enable nextjs@3000 nextjs@3001 && nginx -t && systemctl reload nginx && echo "server ready. Add secrets to /var/www/$APP/shared/.env.production; SSH key command=\"/var/www/$APP/bin/deploy.sh\""
